from pathlib import Path
import json
P=Path(__file__).resolve().parent
packs={gear:json.loads((P/(gear+'-manifest.json')).read_text())['states'][0] for gear in ['bare','helmet']}
html='''<!doctype html><meta charset="utf-8"><title>Bill west inspection candidate</title><style>body{font:16px system-ui;background:#152027;color:#e6eff1;margin:24px}p{max-width:80ch;color:#bdd0d2}select,button{font:inherit;padding:6px}canvas{display:block;margin-top:16px}a{color:#92d9dc}</style><h1>Bill — west inspection</h1><p>Standing diagnostic-reader inspection, with a small button press and glance. Fixed source scale, master matte materials and native west helmet. Candidate loop only; drawing/stowing the reader, cardinal family and runtime selection remain pending.</p><label>Gear <select id="gear"><option value="bare">Bare</option><option value="helmet">Helmet</option></select></label><label>Height <select id="size"><option>148</option><option selected>82</option><option>54</option></select></label><button id="play">Pause</button><button id="step">Next pose</button><span id="status"></span><canvas id="view" width="460" height="430"></canvas><p><a href="../bill-coverage-audit-v1/">Current selected coverage audit</a></p><script>const packs=DATA;let time=0,last=performance.now(),playing=true,manual=0;gear.onchange=()=>{time=0;manual=0};play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play'};step.onclick=()=>{playing=false;manual=(manual+1)%6;play.textContent='Play'};Promise.all(Object.values(packs).map(async s=>s.images=await Promise.all(s.frameFiles.map(f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=f}))))).then(()=>{function draw(now){if(playing)time+=now-last;last=now;let index=playing?Math.floor((time%960)/160):manual;const c=view.getContext('2d');c.fillStyle='#22343e';c.fillRect(0,0,460,215);c.fillStyle='#dae1e0';c.fillRect(0,215,460,215);const f=Number(size.value)/148;for(const y of [190,405])c.drawImage(packs[gear.value].images[index],230-128*f,y-224*f,256*f,256*f);document.getElementById('status').textContent=' pose '+(index+1)+'/6';requestAnimationFrame(draw)}requestAnimationFrame(draw)});</script>'''
(P/'index.html').write_text(html.replace('DATA',json.dumps(packs)))
print('Built inspection candidate playback/step review')
